// Creative Problem Solving Practice Test 6. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–5.
import {q, mix} from './q.js';
const MV='McShane & Von Glinow, Organizational Behavior', AD='Adair, Decision Making & Problem Solving', ST='Sternad, Solve It!', TH='Thinknetic, Critical Thinking & Logic Mastery';
const CRIT='Critical & Effective Thinking', PS='Problem Solving Strategies & Skills', GEN='Clarification of Problems & Generating Ideas', CON='Examining Constraints/Developing Alternatives', LOG='Components of Logic';

export default {
 id:'creative-problem-solving-6',
 event:'Creative Problem Solving',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'McShane & Von Glinow’s Organizational Behavior, Adair’s Decision Making & Problem Solving, Sternad’s Solve It! and Thinknetic’s Critical Thinking & Logic Mastery',
 plan:[{area:CRIT,weight:26},{area:PS,weight:24},{area:GEN,weight:10},{area:CON,weight:20},{area:LOG,weight:20}],
 questions:mix([
  q(CRIT,'A surgeon made a sound decision, but the patient had a rare bad reaction, and reviewers now call the decision poor. What bias is this?','Outcome bias',['Recency bias','Anchoring bias','Halo effect'],'A','A decision should be judged by the information available at the time, not only by how it turned out.',TH),
  q(CRIT,'A clinic with an unusually bad month praises a new policy when the next month is closer to normal, though the policy did little. What explains the improvement?','Regression to the mean',['The placebo effect','Confirmation bias','The halo effect'],'B','Extreme results tend to be followed by more ordinary ones simply by chance.',TH),
  q(CRIT,'A person believes a vague horoscope describes them perfectly, though it would fit almost anyone. What is this effect?','Barnum effect',['Spotlight effect','Decoy effect','Contrast effect'],'C','General statements feel personal because most people can find themselves in them.',TH),
  q(CRIT,'As a hurricane approaches, residents refuse to evacuate because a disaster “has never happened here before.” What bias is this?','Normalcy bias',['Negativity bias','Hindsight bias','Choice overload'],'D','People underestimate the chance and impact of a disaster they have never experienced.',TH),
  q(CRIT,'Parents judge harm caused by giving a vaccine as worse than equal harm caused by not giving it. What bias is this?','Omission bias',['Authority bias','Actor–observer bias','Illusion of control'],'A','People tend to judge harmful actions more harshly than equally harmful failures to act.',TH),
  q(CRIT,'A person chooses $50 today over $70 next month, even though waiting is clearly worth it. What bias is this?','Present bias',['Status quo bias','Information bias','Endowment effect'],'B','Also called hyperbolic discounting, it makes immediate rewards seem larger than they are.',MV),
  q(CRIT,'A patient picks a treatment with a known 70% success rate over one whose success rate is unknown but likely higher. What effect is this?','Ambiguity effect',['Framing effect','Zero-risk bias','Group polarization'],'C','People tend to avoid options when the probability of a good result is unknown.',TH),
  q(CRIT,'A nurse sees three emergencies in one night and concludes that full moons cause busy shifts, though the cases were random. What is this?','Clustering illusion',['Normalcy bias','Ostrich effect','Decoy effect'],'D','Random events often form streaks or clusters that look meaningful but are not.',TH),
  q(CRIT,'Told that they must stop a habit at once, teens do it more to assert their freedom. What is this reaction called?','Reactance',['Social loafing','Groupthink','The Barnum effect'],'A','When people feel their freedom is threatened, they may do the opposite of what is asked.',MV),
  q(CRIT,'A health rumor gains credibility simply because it keeps being repeated in the news and online. What is this process called?','An availability cascade',['A clustering illusion','Regression to the mean','A decoy effect'],'B','Repetition makes an idea easier to recall, and that makes it seem more likely to be true.',TH),
  q(CRIT,'A student with a small stain on their shirt is sure everyone at the conference noticed it. What is this effect?','Spotlight effect',['Halo effect','Barnum effect','IKEA effect'],'C','People overestimate how much others notice their appearance and behavior.',MV),
  q(CRIT,'A pharmacist approves an order because the computer showed no alert, missing an obvious dosing error. What bias is this?','Automation bias',['Present bias','Omission bias','Ambiguity effect'],'D','Automated tools help, but people must still check results with their own judgment.',TH),
  q(CRIT,'A person easily spots biases in others but believes their own thinking is objective. What is this called?','Bias blind spot',['Clustering illusion','Choice overload','Normalcy bias'],'A','Recognizing that everyone, including oneself, has biases is a key part of critical thinking.',TH),
  q(PS,'A team lists each way a new infusion process could fail, its effects and its causes before the process starts. What tool is this?','Failure mode and effects analysis',['Root cause analysis of past events','A strengths and weaknesses review','Pareto analysis of past errors'],'B','FMEA is proactive: it looks for possible failures before they happen.',ST),
  q(PS,'In an FMEA, a failure has a severity of 8, an occurrence of 3 and a detection score of 5. What is its risk priority number?','120',['16','40','24'],'C','RPN = severity × occurrence × detection = 8 × 3 × 5 = 120. Higher numbers get attention first.',ST),
  q(PS,'A chart shows who is responsible, accountable, consulted and informed for each task. What is it called?','A RACI chart',['A SIPOC diagram','A Gantt chart','A run chart'],'D','A RACI chart prevents confusion about roles and makes sure one person is accountable for each task.',ST),
  q(PS,'A team maps every step from a patient’s arrival to discharge, marking which steps add value and where waiting occurs. What is this?','Value stream mapping',['Fault tree analysis','Starbursting','A decision tree'],'A','Value stream maps help Lean teams find waste, such as waiting and extra steps, and remove it.',ST),
  q(PS,'A syringe is designed so it cannot connect to an IV line, preventing a wrong-route error. What is this kind of design called?','Poka-yoke',['Kaizen blitz','Gemba walk','Kanban'],'B','Poka-yoke means mistake-proofing: designing a process so errors are hard or impossible to make.',ST),
  q(PS,'Which structured problem-solving method uses eight disciplines, from forming a team to recognizing its work?','8D',['PDCA','OODA','DMAIC'],'C','8D is common in manufacturing and includes containing the problem and preventing it from recurring.',ST),
  q(PS,'Which problem-solving method, developed from the study of patents, uses 40 inventive principles to resolve contradictions?','TRIZ',['SCAMPER','Synectics','Six Thinking Hats'],'D','TRIZ assumes that many problems have already been solved somewhere in another field.',ST),
  q(PS,'A team draws lines on a floor plan to trace a nurse’s actual walking path during a shift. What tool is this?','A spaghetti diagram',['A swimlane diagram','A control chart','A mind map'],'A','The tangled lines reveal wasted movement and suggest a better layout.',ST),
  q(PS,'Which chart uses bars to show how often values fall into ranges, such as patient wait times grouped by 10 minutes?','Histogram',['Pareto chart','Run chart','Scatter diagram'],'B','A histogram shows the shape of the data, such as whether it is skewed or has two peaks.',ST),
  q(PS,'A line graph shows daily fall counts over time, without control limits. What is it called?','A run chart',['A histogram','A check sheet','A Pareto chart'],'C','Run charts show trends and shifts over time; control charts add statistical limits.',ST),
  q(PS,'A unit applies sort, set in order, shine, standardize and sustain to organize its supply room. What method is this?','5S',['5 Whys','5W1H','8D'],'D','5S creates an orderly workplace where problems and missing items are easy to see.',ST),
  q(PS,'In Lewin’s change model, which three stages does a team move through?','Unfreeze, change, refreeze',['Plan, do, check','Define, measure, improve','Observe, orient, act'],'A','Unfreezing creates readiness for change, and refreezing makes the new way stick.',MV),
  q(GEN,'In de Bono’s Six Thinking Hats, which hat looks for risks and reasons an idea might fail?','Black hat',['White hat','Yellow hat','Green hat'],'B','The black hat is cautious judgment; the yellow hat looks for benefits.',AD),
  q(GEN,'A team pairs two unrelated objects, such as a wheelchair and a backpack, to spark a new product idea. What technique is this?','Forced connections',['Assumption reversal','Paired comparison','Affinity grouping'],'C','Linking unrelated things pushes thinking beyond obvious solutions.',AD),
  q(GEN,'Each team member folds a page into eight panels and sketches eight ideas in eight minutes. What technique is this?','Crazy 8s',['Six-hat thinking','Storyboarding','The lotus blossom'],'D','The short time limit pushes people past their first, most obvious ideas and stops overthinking.',AD),
  q(GEN,'Team members take turns sharing one idea each, in order, until ideas run out. What technique is this?','Round-robin brainstorming',['The Delphi technique','Starbursting','Rolestorming'],'A','Taking turns makes sure quieter members contribute and no one dominates.',AD),
  q(GEN,'A team writes a central problem in the middle of a grid, surrounds it with eight themes, and then expands each theme into eight more ideas. What is this technique?','Lotus blossom',['Fishbone diagram','Morphological box','Affinity diagram'],'B','The lotus blossom moves from a core problem outward to many detailed ideas.',AD),
  q(CON,'Before negotiating a supply contract, a manager identifies what they will do if no agreement is reached. What is this called?','BATNA',['ROI','SWOT','RACI'],'C','The best alternative to a negotiated agreement sets the point at which walking away makes sense.',AD),
  q(CON,'Program X costs $40,000 and prevents 20 hospital stays. Program Y costs $45,000 and prevents 30. Which is more cost-effective?','Program Y, at $1,500 per stay prevented',['Program X, at $2,000 per stay prevented','Program X, because it costs less in total','Both are equal, since the costs are similar'],'D','Divide cost by results: X = $2,000 and Y = $1,500 per stay prevented, so Y gives more value.',AD),
  q(CON,'A decision maker picks the option that is best on the most important criterion and uses the next criterion only to break ties. What rule is this?','Lexicographic rule',['Weighted scoring','Laplace criterion','Minimax regret'],'A','This rule is fast but ignores how options compare on less important criteria.',AD),
  q(CON,'A team removes every option that fails one criterion at a time, starting with the most important, until one remains. What strategy is this?','Elimination by aspects',['Paired comparison','Sensitivity analysis','Brainwriting'],'B','This noncompensatory strategy simplifies choices but can drop a strong option early.',AD),
  q(CON,'In a weighted decision matrix, a high score on one criterion can make up for a low score on another. What type of decision rule is this?','Compensatory',['Noncompensatory','Lexicographic','Dominated'],'C','Compensatory rules let strengths offset weaknesses; noncompensatory rules do not.',AD),
  q(CON,'After a hospital adds hand-hygiene audits and alcohol rub stations, some infection risk still remains. What is this remaining risk called?','Residual risk',['Avoided risk','Transferred risk','Inherent risk'],'D','Residual risk is what is left after controls are in place; inherent risk is the level before them.',AD),
  q(CON,'A health agency restricts a new chemical before harm is fully proven because the possible damage is serious and irreversible. What principle is this?','Precautionary principle',['Pareto principle','Peter principle','Principle of parsimony'],'A','When harm could be severe, lack of full certainty is not a reason to delay protective action.',AD),
  q(CON,'Why should a team include “do nothing” as an option when comparing alternatives?','It gives a baseline to judge whether change is worth it',['It is always the cheapest and safest choice','It removes the need to gather any more data','It is required by every decision-making model'],'B','Comparing options with the status quo shows what each change would really add.',AD),
  q(CON,'Clinic A serves 400 patients for $12,000 and Clinic B serves 250 patients for $9,000. Which has the lower cost per patient?','Clinic A, at $30 per patient',['Clinic B, at $30 per patient','Clinic B, at $36 per patient','Clinic A, at $36 per patient'],'C','$12,000 ÷ 400 = $30 for A, and $9,000 ÷ 250 = $36 for B, so A costs less per patient.',AD),
  q(CON,'A city pays a bounty for dead rats, so people start breeding rats to collect it. What is this kind of result called?','A perverse incentive',['A hard constraint','A sunk cost','A residual risk'],'D','Also called the cobra effect, it shows how a reward can produce the opposite of what was intended.',AD),
  q(LOG,'“No real nurse would ever complain about long shifts.” When shown a nurse who does, the speaker says she is not a real nurse. Which fallacy is this?','No true Scotsman',['Appeal to authority','Red herring','Straw man'],'A','The speaker changes the definition to protect a claim from any counterexample.',TH),
  q(LOG,'“We have always used this paper form, so it must be the right way.” Which fallacy is this?','Appeal to tradition',['Appeal to novelty','Hasty generalization','Equivocation'],'B','Something being old or customary does not prove it is correct or best.',TH),
  q(LOG,'A supplement company quotes only the two small studies that favored its product and ignores ten that did not. Which fallacy is this?','Cherry-picking',['Middle ground','Moving the goalposts','Tu quoque'],'C','Selecting only supporting evidence gives a misleading picture of what the data shows.',TH),
  q(LOG,'“Skipping one dose of a vitamin is just as dangerous as skipping a dose of insulin, since both are missed medicines.” Which fallacy is this?','False equivalence',['False dilemma','Appeal to nature','Genetic fallacy'],'D','Two things that share one feature are treated as equal even though they differ greatly in importance.',TH),
  q(LOG,'“You cannot prove my cure doesn’t work, so you must accept that it does.” Which error in reasoning shifts the work of proof?','Shifting the burden of proof',['Affirming the consequent','Composition','Division'],'A','The person making a claim is responsible for supporting it with evidence.',TH),
  q(LOG,'“If this test result were accurate, I would need surgery, so the result must be wrong.” Which fallacy is this?','Appeal to consequences',['Appeal to tradition','Hasty generalization','Personal incredulity'],'B','Whether a conclusion is pleasant or unpleasant has no bearing on whether it is true.',TH),
  q(LOG,'“Exclusive or” (XOR) is true when which condition is met?','Exactly one of the statements is true',['Both statements are true','Both statements are false','At least one statement is false'],'C','Inclusive or is true when one or both are true; exclusive or excludes the case where both are true.',TH),
  q(LOG,'“Obesity is caused only by eating too much sugar.” Which fallacy is this?','Fallacy of the single cause',['Appeal to tradition','Appeal to consequences','No true Scotsman'],'D','Most health outcomes, including obesity, have several causes such as genes, activity and sleep working together.',TH),
  q(LOG,'“This app was released last week, so it must be better than the older one.” Which fallacy is this?','Appeal to novelty',['Appeal to tradition','Cherry-picking','Bandwagon'],'A','Newer is not automatically better; claims of improvement need evidence.',TH),
  q(LOG,'“I can’t imagine how vaccines could possibly work, so they must not.” Which fallacy is this?','Personal incredulity',['Appeal to ignorance','Argument from silence','Anecdotal evidence'],'B','Finding something hard to understand or imagine does not make it false; the evidence decides.',TH)
 ],9639)
};
